// Runs `devcontainer features test` for the collection. Requires Docker.
// Features with test/<id>/scenarios.json declare their prerequisites there and run as scenarios;
// all others run the autogenerated test.sh on the CPU base image from stack.json.
import { existsSync } from "node:fs";
import { join } from "node:path";
import { devcontainer, featureIds, featuresRoot, loadStack } from "./stack.ts";

const stack = loadStack();
const selected = process.argv.slice(2);
const ids = selected.length ? selected : featureIds();
const hasScenarios = (id: string) => existsSync(join(featuresRoot, "test", id, "scenarios.json"));
const standalone = ids.filter(id => !hasScenarios(id));
const scenario = ids.filter(hasScenarios);
const common = ["features", "test", "--project-folder", featuresRoot, "--skip-duplicated"];

if (standalone.length) {
  devcontainer([...common, "--skip-scenarios", "--base-image", stack.variants.cpu.buildArgs.BASE_IMAGE,
    "--features", ...standalone], { inherit: true });
}
if (scenario.length) {
  devcontainer([...common, "--skip-autogenerated", "--features", ...scenario], { inherit: true });
}
